def calculate_k_max_bound(N):
    # Total edges in K_N
    E = N * (N - 1) // 2
    # Minimum edges required for k connected subgraphs
    # k * (N - 1) <= E
    # k <= E / (N - 1)
    if N <= 1:
        return 0
    k_max_bound = E / (N - 1)
    return int(k_max_bound)

Ns = [3, 5, 7]
results = {}
for N in Ns:
    k_max = calculate_k_max_bound(N)
    results[N] = k_max
    print(f"For N={N}, k_max bound is {k_max}")
